def compute(vars):
    cost = vars["v1"]
    period = vars["v2"]

    if period == 0:
        return None

    annual_recognition = cost / period

    return {
        "value": annual_recognition,
        "trace": {
            "unrecognized_compensation_cost": cost,
            "weighted_average_recognition_period": period,
            "annual_recognition": annual_recognition,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "monetary amount"
            }
        }
    }
